// @vitest-environment node
import { test } from "vitest";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { z } from "zod";
import { ledgerWithHouseholds, type Household, type ProjectedExpense } from "../../src/domain/householdProjection.ts";
import type { Ledger } from "../../src/domain/ledger.ts";
import { yearReview, yearReviewBannerYear, yearReviewYear, type YearReview } from "../../src/domain/yearReview.ts";

// MAZ-292 phase 2: contracts/fixtures/year-review.json, generated by
// scripts/fixtures/year-review.ts. The Swift rule reads the same file (YearReviewTests.swift).
const date = z.string().regex(/^\d{4}-\d{2}-\d{2}$/);
const Fixture = z.strictObject({
  generator: z.string(),
  description: z.string(),
  households: z.array(z.strictObject({ id: z.string(), name: z.string(), memberCount: z.number().int(), trip: z.strictObject({ startDate: date, endDate: date }).optional() })),
  ledgers: z.record(z.string(), z.custom<Ledger>((value) => typeof value === "object" && value !== null)),
  projections: z.record(z.string(), z.array(z.custom<ProjectedExpense>((value) => typeof value === "object" && value !== null))),
  cases: z.array(z.strictObject({ name: z.string(), ledger: z.string(), projection: z.string(), year: z.string().regex(/^\d{4}$/), today: date, expected: z.custom<YearReview>() })).min(6),
  window: z.array(z.strictObject({ today: date, year: z.string().nullable(), banner: z.string().nullable() })).min(6),
});
const golden = Fixture.parse(JSON.parse(readFileSync(new URL("contracts/fixtures/year-review.json", new URL("../../../../", import.meta.url)), "utf8")));
const households = golden.households as Pick<Household, "id" | "memberCount" | "trip">[];

test("year-review fixtures: the year in review is computed from the year's recorded months", () => {
  const names = golden.cases.map((item) => item.name);
  for (const required of ["a first year", "a year with only previews", "a year with no entries"]) assert.ok(names.some((name) => name.startsWith(required)), required);
  for (const item of golden.cases) {
    const ledger = golden.ledgers[item.ledger]!;
    const projection = golden.projections[item.projection]!;
    const review = yearReview(ledgerWithHouseholds(ledger, projection), item.year, { today: item.today, households });
    assert.deepEqual(JSON.parse(JSON.stringify(review)), item.expected, item.name);

    // Independent checks of the rule's invariants.
    assert.equal(review.months.length, 12, item.name);
    assert.equal(review.months.reduce((sum, month) => sum + month.spent, 0), review.spent, item.name);
    assert.ok(review.topCategories.every((category) => Number.isFinite(category.share)), item.name);
    assert.ok(review.trips.daysAway <= review.trips.list.reduce((sum, trip) => sum + trip.days, 0), item.name);
    const foreign = projection.filter((row) => row.householdCurrency !== ledger.currency || row.scheduled).map((row) => row.date);
    assert.ok(review.shared.count <= projection.length - foreign.length, item.name);
    assert.ok(review.shared.payers.reduce((sum, payer) => sum + payer.count, 0) <= review.shared.count, item.name);
    if (review.from === null) assert.deepEqual([review.trips.list, review.facts.daysWithoutSpending], [[], 0], item.name);
  }
});

test("year-review fixtures: shared rows in another currency and shared previews never count", () => {
  const item = golden.cases.find((candidate) => candidate.projection === "households")!;
  const review = yearReview(ledgerWithHouseholds(golden.ledgers[item.ledger]!, golden.projections[item.projection]!), item.year, { today: item.today, households });
  const lisbon = review.trips.list.find((trip) => trip.id === "lisbon")!;
  // The flight (personal, on the linked trip) and three shared shares in CAD; the EUR taxi is left out.
  assert.equal(lisbon.share, 64000 + 52000 + 8000 + 2000);
  assert.ok(!review.shared.payers.some((payer) => payer.payer?.email === "gone@example.test" && payer.payer.displayName), "a deleted payer has no name");
});

test("year-review fixtures: offered from December 26 to January 31, with the banner in January", () => {
  for (const item of golden.window) {
    assert.equal(yearReviewYear(item.today), item.year, item.today);
    assert.equal(yearReviewBannerYear(item.today), item.banner, item.today);
  }
});
